package dev.sablelife.heart;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;
class AdaptiveDefenseTest {
    @Test void DisabledAndBelowThresholdPreserveDamage(){var d=new AdaptiveDefense();assertEquals(300,d.apply(300,0));assertEquals(0,d.dps());d.configure(true,100,80,20);assertEquals(20,d.apply(20,0));assertEquals(30,d.apply(30,1));assertEquals(50,d.dps());assertEquals(0,d.reduction());}
    @Test void AllHitsAndTheCurrentHitCountBeforeAdaptiveReduction(){var d=new AdaptiveDefense();d.configure(true,100,80,20);assertEquals(100,d.apply(100,0));assertEquals(50,d.apply(100,0));assertEquals(100f/3,d.apply(100,0),.001);assertEquals(300,d.dps());assertEquals(2./3,d.reduction(),1e-9);assertEquals(1,d.buckets());}
    @Test void SustainedDamageDoesNotOscillateWhenActualHpLossDrops(){var d=new AdaptiveDefense();d.configure(true,100,80,20);for(int t=0;t<100;t++){float damage=d.apply(15,t);if(t>=20){assertEquals(5,damage,.001);assertEquals(300,d.dps(),.001);}}}
    @Test void MaximumIsBoundedAndNeverFullImmunity(){var d=new AdaptiveDefense();assertFalse(d.configure(true,100,100,20));d.configure(true,100,80,20);assertEquals(2000,d.apply(10000,0),.001);assertEquals(.8,d.reduction(),1e-9);d.configure(true,.1,95,2);assertTrue(d.apply(Float.MIN_VALUE,0)>0);assertTrue(Float.isFinite(d.apply(Float.MAX_VALUE,0)));}
    @Test void ExpiringDamageRecoversSmoothlyEvenWithoutMoreHits(){var d=new AdaptiveDefense();d.configure(true,100,80,20);d.apply(1000,0);d.tick(19);assertEquals(.8,d.reduction(),1e-9);d.tick(20);assertEquals(0,d.dps());assertTrue(d.reduction()>0&&d.reduction()<.8);d.tick(32);assertTrue(d.reduction()<.2);d.tick(120);assertEquals(0,d.reduction());}
    @Test void ConfigurationResetReloadAndClockRollbackDropOldStatistics(){var d=new AdaptiveDefense();d.configure(true,100,80,20);d.apply(1000,100);d.tick(99);assertEquals(0,d.dps());d.apply(1000,100);d.configure(false,100,80,20);assertEquals(0,d.reduction());d.configure(true,100,80,20);assertEquals(0,d.dps());d.apply(1000,0);d.reset();assertEquals(0,d.dps());assertEquals(0,d.reduction());}
    @Test void RejectedDamageDoesNotPolluteHistoryAndPerTickAggregationIsBounded(){var d=new AdaptiveDefense();d.configure(true,100,80,200);assertEquals(0,d.apply(Float.NaN,0));assertEquals(0,d.apply(Float.POSITIVE_INFINITY,0));assertEquals(0,d.apply(-1,0));assertEquals(0,d.buckets());for(int t=0;t<1000;t++){for(int i=0;i<50;i++)d.apply(1,t);}assertTrue(d.buckets()<=200);assertFalse(d.configure(true,0,80,20));assertFalse(d.configure(true,100,-1,20));assertFalse(d.configure(true,100,80,201));}
}
